<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserRoleAssignmentUserAccessor
{
    private UserRoleAssignmentUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserRoleAssignmentUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserRoleAssignmentUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserRoleAssignmentUserVO::from($user);
        return $copy;
    }
}
